import {ErrorBoundary} from '@github-ui/react-core/error-boundary'
import {verifiedFetchJSON} from '@github-ui/verified-fetch'
import {CheckIcon, LinkExternalIcon, MeterIcon, PlayIcon, SkipIcon} from '@primer/octicons-react'
import {Button, Heading, Link} from '@primer/react'
import {clsx} from 'clsx'
import type React from 'react'
import {useCallback, useEffect, useMemo, useState} from 'react'

import styles from './AutomatedCodeReviewRulesets.module.css'

export interface RulesetRule {
  reviewOnPush: boolean
  reviewDraftPullRequests: boolean
}

export interface RulesetInfo {
  id: number
  name: string
  enforcement: 'enabled' | 'evaluate' | 'disabled'
  url: string
  ruleConfigurationsCount: number
  conditionsCount: number
  rule: RulesetRule | null
}

interface TargetCountRow {
  rulesetId: number
  count?: number
  errorMessage?: string
}

type TargetCountsMap = Record<number, TargetCountRow>

export interface AutomatedCodeReviewRulesetsProps {
  orgRulesets: RulesetInfo[]
  repoRulesets: RulesetInfo[]
  orgOwnerName: string
  viewAllRulesetsUrl: string
  createRulesetUrl: string
  deferredTargetCountsUrl: string
  docsUrl: string
}

interface SubheadProps {
  heading: string
  description: React.ReactNode
}

const Subhead: React.FC<SubheadProps> = ({heading, description}) => {
  return (
    <div className="Subhead border-bottom-0 mb-2 d-flex flex-justify-between flex-items-center">
      <div className="d-flex flex-column">
        <h2 className="Subhead-heading f4 text-semibold h1-override-shared-component">{heading}</h2>
        <p className="Subhead-description mb-1">{description}</p>
      </div>
    </div>
  )
}

interface BorderBoxProps {
  name: React.ReactNode
  renderButton?(): React.ReactElement | null
  children: React.ReactNode
}

const BorderBox: React.FC<BorderBoxProps> = ({name, renderButton, children}) => {
  return (
    <div className="Box">
      <div
        className={clsx(
          styles.BoxHeader,
          'Box-header d-flex flex-justify-between flex-items-center pt-2 pb-2 tmp-pr-3',
        )}
      >
        <h3 className="Box-title f5">{name}</h3>
        {renderButton?.() || null}
      </div>
      {children}
    </div>
  )
}

function pluralize(count: number, singular: string, plural?: string): string {
  if (count === 1) return `${count} ${singular}`
  return `${count} ${plural ?? `${singular}s`}`
}

function targetText(info: TargetCountRow | undefined, conditionsCount: number, orgManaged: boolean): string {
  if (info?.errorMessage) {
    const base = 'targeting branches (too many to display)'
    return orgManaged ? `${base} in this repository` : base
  }
  if (info?.count !== undefined) {
    const base = `targeting ${pluralize(info.count, 'branch', 'branches')}`
    return orgManaged ? `${base} in this repository` : base
  }
  const base = `targeting ${pluralize(conditionsCount, 'branch condition')}`
  return orgManaged ? `${base} in this repository` : base
}

interface EnforcementIconProps {
  enforcement: RulesetInfo['enforcement']
}

const EnforcementIcon: React.FC<EnforcementIconProps> = ({enforcement}) => {
  switch (enforcement) {
    case 'enabled':
      return <PlayIcon className="color-fg-success" size={16} aria-label="Active" />
    case 'evaluate':
      return <MeterIcon className="color-fg-severe" size={16} aria-label="Evaluate" />
    default:
      return <SkipIcon className="color-fg-muted" size={16} aria-label="Disabled" />
  }
}

interface RuleCheckItemProps {
  label: string
  withBottomBorder?: boolean
}

const RuleCheckItem: React.FC<RuleCheckItemProps> = ({label, withBottomBorder = false}) => (
  <div className="d-flex flex-1">
    <span>
      <CheckIcon className="color-fg-muted" size={16} />
    </span>
    <div className="d-flex flex-1 ml-2">
      <div className={clsx('color-fg-default text-bold flex-1', withBottomBorder && styles.RuleItemDivider)}>
        {label}
      </div>
    </div>
  </div>
)

interface RuleDetailsProps {
  rule: RulesetRule
}

const RuleDetails: React.FC<RuleDetailsProps> = ({rule}) => {
  const reviewOnPushEnabled = rule.reviewOnPush
  const reviewDraftPrsEnabled = rule.reviewDraftPullRequests

  return (
    <div className="d-flex Box-row tmp-px-3 pt-0 pb-2 flex-justify-between flex-items-center bgColor-inset">
      <div className="d-flex flex-1 flex-column">
        <div className="mt-2">
          <RuleCheckItem
            label="Automated code reviews on push"
            withBottomBorder={reviewDraftPrsEnabled || reviewOnPushEnabled}
          />
        </div>

        {(reviewOnPushEnabled || reviewDraftPrsEnabled) && (
          <div className="d-flex flex-1 tmp-ml-4 pt-2 flex-column">
            {reviewOnPushEnabled && (
              <RuleCheckItem label="Review new pushes" withBottomBorder={reviewDraftPrsEnabled} />
            )}
            <div className={reviewOnPushEnabled ? 'pt-2' : ''} />
            {reviewDraftPrsEnabled && <RuleCheckItem label="Review draft pull requests" />}
          </div>
        )}
      </div>
    </div>
  )
}

interface RulesetSummaryProps {
  ruleset: RulesetInfo
  targetCount: TargetCountRow | undefined
  orgManaged: boolean
}

const RulesetSummary: React.FC<RulesetSummaryProps> = ({ruleset, targetCount, orgManaged}) => {
  const ruleText = pluralize(ruleset.ruleConfigurationsCount, 'Copilot code review rule')
  const target = targetText(targetCount, ruleset.conditionsCount, orgManaged)

  return (
    <div className="Box-row d-flex tmp-px-3 py-2 flex-justify-between flex-items-center">
      <div className="d-flex flex-items-start gap-2">
        <span>
          <EnforcementIcon enforcement={ruleset.enforcement} />
        </span>
        <div className="d-flex flex-column">
          <Link href={ruleset.url} className="color-fg-default text-bold">
            {ruleset.name}
          </Link>
          <div className="text-small color-fg-muted">
            {ruleText} • {target}
          </div>
        </div>
      </div>
    </div>
  )
}

interface RulesetRowProps {
  ruleset: RulesetInfo
  targetCount: TargetCountRow | undefined
  orgManaged: boolean
}

const RulesetRow: React.FC<RulesetRowProps> = ({ruleset, targetCount, orgManaged}) => (
  <>
    <RulesetSummary ruleset={ruleset} targetCount={targetCount} orgManaged={orgManaged} />
    {ruleset.rule && <RuleDetails rule={ruleset.rule} />}
  </>
)

interface ViewAllRulesetsButtonProps {
  href: string
}

const ViewAllRulesetsButton: React.FC<ViewAllRulesetsButtonProps> = ({href}) => (
  <Link href={href} id="view-all-rulesets-button" className={styles.ViewAllRulesetsLink}>
    View all rulesets
    <LinkExternalIcon size={16} />
  </Link>
)

interface RulesetsPanelProps {
  rulesets: RulesetInfo[]
  orgManaged: boolean
  orgOwnerName: string
  viewAllRulesetsUrl: string
  targetCounts: TargetCountsMap
}

const RulesetsPanel: React.FC<RulesetsPanelProps> = ({
  rulesets,
  orgManaged,
  orgOwnerName,
  viewAllRulesetsUrl,
  targetCounts,
}) => {
  const countLabel = orgManaged ? 'organization ruleset' : 'ruleset'
  const title = pluralize(rulesets.length, countLabel)

  return (
    <BorderBox
      name={<span data-testid={`${orgManaged ? 'organization' : 'repository'}-rulesets-title`}>{title}</span>}
      renderButton={() =>
        orgManaged ? (
          <span className="text-small color-fg-muted mt-1">Managed by {orgOwnerName}</span>
        ) : (
          <ViewAllRulesetsButton href={viewAllRulesetsUrl} />
        )
      }
    >
      <ul className="list-style-none">
        {rulesets.map(ruleset => (
          <li key={ruleset.id}>
            <RulesetRow ruleset={ruleset} targetCount={targetCounts[ruleset.id]} orgManaged={orgManaged} />
          </li>
        ))}
      </ul>
    </BorderBox>
  )
}

interface EmptyRulesetsPanelProps {
  viewAllRulesetsUrl: string
  createRulesetUrl: string
}

const EmptyRulesetsPanel: React.FC<EmptyRulesetsPanelProps> = ({viewAllRulesetsUrl, createRulesetUrl}) => {
  const [isCreating, setIsCreating] = useState(false)

  const handleCreateRuleset = useCallback(async () => {
    setIsCreating(true)
    try {
      const response = await verifiedFetchJSON(createRulesetUrl, {method: 'POST'})
      if (response.ok) {
        const data = (await response.json()) as {url?: string}
        if (data.url) {
          window.location.assign(data.url)
          return
        }
      }
    } catch {
      // fall through to reset loading state
    }
    setIsCreating(false)
  }, [createRulesetUrl])

  return (
    <BorderBox name="No rulesets" renderButton={() => <ViewAllRulesetsButton href={viewAllRulesetsUrl} />}>
      <div className="Box-row d-flex flex-column flex-items-center tmp-p-4">
        <Heading as="h3" data-testid="empty-rulesets-title" className="f4 text-bold tmp-mb-3">
          Automate Copilot code reviews
        </Heading>
        <Button variant="primary" id="create-ruleset-button" onClick={handleCreateRuleset} loading={isCreating}>
          Create ruleset for default branch
        </Button>
      </div>
    </BorderBox>
  )
}

function useTargetCounts(rulesetIds: number[], deferredTargetCountsUrl: string): TargetCountsMap {
  const [targetCounts, setTargetCounts] = useState<TargetCountsMap>({})
  const idsKey = rulesetIds.join(',')

  useEffect(() => {
    if (rulesetIds.length === 0) return

    const controller = new AbortController()

    async function fetchTargetCounts() {
      try {
        const response = await verifiedFetchJSON(deferredTargetCountsUrl, {
          method: 'POST',
          body: {ruleset_ids: rulesetIds},
          signal: controller.signal,
        })
        if (!response.ok) return
        const data = (await response.json()) as {preview: TargetCountRow[]}
        if (!data?.preview) return

        const map: TargetCountsMap = {}
        for (const row of data.preview) {
          map[row.rulesetId] = row
        }
        setTargetCounts(map)
      } catch {
        // Ignore fetch errors (including AbortError) — target counts are best-effort
        return
      }
    }

    fetchTargetCounts()

    return () => {
      controller.abort()
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [idsKey, deferredTargetCountsUrl])

  return targetCounts
}

const AutomatedCodeReviewRulesetsInner: React.FC<AutomatedCodeReviewRulesetsProps> = ({
  orgRulesets,
  repoRulesets,
  orgOwnerName,
  viewAllRulesetsUrl,
  createRulesetUrl,
  deferredTargetCountsUrl,
  docsUrl,
}) => {
  const allRulesetIds = useMemo(() => [...orgRulesets, ...repoRulesets].map(r => r.id), [orgRulesets, repoRulesets])
  const targetCounts = useTargetCounts(allRulesetIds, deferredTargetCountsUrl)

  const totalRulesets = orgRulesets.length + repoRulesets.length
  const containsOrgManagedRules = orgRulesets.length > 0

  return (
    <div data-testid="automated-code-reviews-rulesets" id="automated-code-reviews-rulesets" className="tmp-mt-4">
      <Subhead
        heading="Manage Copilot code review automations"
        description={
          <>
            Use rulesets to automatically request reviews and more.{' '}
            <Link href={docsUrl} className="Link--inTextBlock">
              Learn how to set up rulesets.
            </Link>
          </>
        }
      />

      {totalRulesets > 0 ? (
        <>
          {containsOrgManagedRules && (
            <RulesetsPanel
              rulesets={orgRulesets}
              orgManaged
              orgOwnerName={orgOwnerName}
              viewAllRulesetsUrl={viewAllRulesetsUrl}
              targetCounts={targetCounts}
            />
          )}
          {repoRulesets.length > 0 && (
            <div className={containsOrgManagedRules ? 'tmp-mt-5' : ''}>
              <RulesetsPanel
                rulesets={repoRulesets}
                orgManaged={false}
                orgOwnerName={orgOwnerName}
                viewAllRulesetsUrl={viewAllRulesetsUrl}
                targetCounts={targetCounts}
              />
            </div>
          )}
        </>
      ) : (
        <EmptyRulesetsPanel viewAllRulesetsUrl={viewAllRulesetsUrl} createRulesetUrl={createRulesetUrl} />
      )}
    </div>
  )
}

export const AutomatedCodeReviewRulesets: React.FC<AutomatedCodeReviewRulesetsProps> = props => (
  <ErrorBoundary boundaryName="AutomatedCodeReviewRulesets" fallback={null}>
    <AutomatedCodeReviewRulesetsInner {...props} />
  </ErrorBoundary>
)
